CREATE TABLE usuarios (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(100) NOT NULL, correo VARCHAR(254) NOT NULL UNIQUE, contrasena VARCHAR(72) NOT NULL, rol VARCHAR(20) NOT NULL DEFAULT 'USUARIO' CHECK (rol IN ('USUARIO','MODERADOR','ADMINISTRADOR')), activo BOOLEAN NOT NULL DEFAULT TRUE, creado_en TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ingredientes (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE recetas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(150) NOT NULL, descripcion TEXT, minutos_preparacion SMALLINT CHECK(minutos_preparacion > 0), creador_id BIGINT NOT NULL REFERENCES usuarios(id), creado_en TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ingredientes_receta (receta_id BIGINT REFERENCES recetas(id) ON DELETE CASCADE, ingrediente_id BIGINT REFERENCES ingredientes(id), cantidad NUMERIC(10,2), unidad VARCHAR(30), PRIMARY KEY(receta_id, ingrediente_id));
CREATE TABLE pasos_receta (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, receta_id BIGINT NOT NULL REFERENCES recetas(id) ON DELETE CASCADE, orden SMALLINT NOT NULL, instruccion TEXT NOT NULL, UNIQUE(receta_id,orden));
CREATE TABLE favoritos (usuario_id BIGINT REFERENCES usuarios(id) ON DELETE CASCADE, receta_id BIGINT REFERENCES recetas(id) ON DELETE CASCADE, creado_en TIMESTAMPTZ DEFAULT now(), PRIMARY KEY(usuario_id,receta_id));
CREATE TABLE despensas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT NOT NULL UNIQUE REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE ingredientes_despensa (despensa_id BIGINT REFERENCES despensas(id) ON DELETE CASCADE, ingrediente_id BIGINT REFERENCES ingredientes(id), cantidad NUMERIC(10,2), unidad VARCHAR(30), PRIMARY KEY(despensa_id,ingrediente_id));
CREATE TABLE historial_recetas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuarios(id), receta_id BIGINT NOT NULL REFERENCES recetas(id), visto_en TIMESTAMPTZ DEFAULT now());
CREATE TABLE menus_semanales (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuarios(id), semana DATE NOT NULL, UNIQUE(usuario_id,semana));
CREATE TABLE listas_compra (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT NOT NULL REFERENCES usuarios(id), nombre VARCHAR(100) NOT NULL, creada_en TIMESTAMPTZ DEFAULT now());
CREATE TABLE elementos_lista_compra (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, lista_id BIGINT NOT NULL REFERENCES listas_compra(id) ON DELETE CASCADE, nombre VARCHAR(100) NOT NULL, comprado BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE etiquetas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nombre VARCHAR(60) NOT NULL UNIQUE); CREATE TABLE recetas_etiquetas (receta_id BIGINT REFERENCES recetas(id) ON DELETE CASCADE,etiqueta_id BIGINT REFERENCES etiquetas(id),PRIMARY KEY(receta_id,etiqueta_id));
CREATE TABLE restricciones_alimentarias (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nombre VARCHAR(80) UNIQUE NOT NULL); CREATE TABLE alergias (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,nombre VARCHAR(80) UNIQUE NOT NULL); CREATE TABLE usuarios_restricciones (usuario_id BIGINT REFERENCES usuarios(id) ON DELETE CASCADE,restriccion_id BIGINT REFERENCES restricciones_alimentarias(id),PRIMARY KEY(usuario_id,restriccion_id)); CREATE TABLE usuarios_alergias (usuario_id BIGINT REFERENCES usuarios(id) ON DELETE CASCADE,alergia_id BIGINT REFERENCES alergias(id),PRIMARY KEY(usuario_id,alergia_id));
CREATE TABLE comentarios (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, receta_id BIGINT REFERENCES recetas(id) ON DELETE CASCADE, usuario_id BIGINT REFERENCES usuarios(id), contenido TEXT NOT NULL, creado_en TIMESTAMPTZ DEFAULT now()); CREATE TABLE resenas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, receta_id BIGINT REFERENCES recetas(id) ON DELETE CASCADE, usuario_id BIGINT REFERENCES usuarios(id), puntuacion SMALLINT CHECK(puntuacion BETWEEN 1 AND 5), UNIQUE(receta_id,usuario_id)); CREATE TABLE reportes (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, usuario_id BIGINT REFERENCES usuarios(id), receta_id BIGINT REFERENCES recetas(id), motivo TEXT NOT NULL, estado VARCHAR(20) DEFAULT 'PENDIENTE'); CREATE TABLE imagenes (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, receta_id BIGINT NOT NULL REFERENCES recetas(id) ON DELETE CASCADE, url TEXT NOT NULL, identificador_publico VARCHAR(255) NOT NULL UNIQUE);
CREATE INDEX indice_recetas_nombre ON recetas USING gin (to_tsvector('spanish',nombre)); CREATE INDEX indice_ingredientes_receta ON ingredientes_receta(ingrediente_id,receta_id); CREATE INDEX indice_historial_usuario ON historial_recetas(usuario_id,visto_en DESC);
